    var uploadPick = function () {
      var input = document.createElement('input');
      input.type = 'file';
      input.accept = '.html,text/html';
      input.addEventListener('change', function () {
        if (!input.files.length) return;
        var fd = new FormData();
        fd.append('file', input.files[0]);
        toast('Uploading experience\u2026');
        fetch(cfg.mediaUrl, {
          method: 'POST',
          headers: { 'X-WP-Nonce': cfg.nonce },
          credentials: 'same-origin',
          body: fd,
        }).then(function (res) {
          if (!res.ok) throw new Error('HTTP ' + res.status);
          return res.json();
        }).then(function (item) {
          landExp(item.id, item.source_url, null);
        }).catch(function (err) {
          toast('Upload failed \u2014 .html uploads need admin rights.', { ttl: 6000 });
          console.error('gogh experience upload failed:', err);
        });
      });
      input.click();
    };
    // the gallery law: calm walls, wild frames. Experiences ride their own
    // flag now (the section-level ask tier is parked, this door is not):
    // keyless admins get the paste door RIGHT HERE — the key lives where
