      (logoImgs.length ? '<button type="button" class="gogh-hdoor gogh-logo-totext"><span>Use a text name instead</span><span class="gogh-hdoor-chev">\u203a</span></button>' : '') +
      '</div>';
    var closeX = panel.querySelector('.gogh-panel-close');
